import React from 'react';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import {
  AppBar,
  Toolbar,
  Typography,
  Button,
  Box,
  Menu,
  MenuItem,
  IconButton,
} from '@mui/material';
import MovieIcon from '@mui/icons-material/Movie';
import SearchIcon from '@mui/icons-material/Search';
import MenuIcon from '@mui/icons-material/Menu';

const Navbar = () => {
  const navigate = useNavigate();
  const token = localStorage.getItem('token');
  const [anchorEl, setAnchorEl] = React.useState(null);

  const handleMenu = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  const handleTypeClick = (type) => {
    navigate(`/type/${type}`);
    handleClose();
  };

  return (
    <AppBar position="static">
      <Toolbar>
        <MovieIcon sx={{ mr: 2 }} />
        <Typography
          variant="h6"
          component={RouterLink}
          to="/"
          sx={{
            flexGrow: 1,
            textDecoration: 'none',
            color: 'inherit',
          }}
        >
          CineFlex
        </Typography>
        <Box sx={{ display: 'flex', alignItems: 'center' }}>
          {token ? (
            <>
              <IconButton
                color="inherit"
                component={RouterLink}
                to="/search"
                sx={{ mr: 2 }}
              >
                <SearchIcon />
              </IconButton>
              <Button
                color="inherit"
                onClick={handleMenu}
                startIcon={<MenuIcon />}
                sx={{ mr: 2 }}
              >
                Browse
              </Button>
              <Menu
                anchorEl={anchorEl}
                open={Boolean(anchorEl)}
                onClose={handleClose}
              >
                <MenuItem onClick={() => handleTypeClick('movie')}>Movies</MenuItem>
                <MenuItem onClick={() => handleTypeClick('tv_show')}>TV Shows</MenuItem>
                <MenuItem onClick={() => handleTypeClick('series')}>Series</MenuItem>
              </Menu>
              <Button
                color="inherit"
                component={RouterLink}
                to="/history"
                sx={{ mr: 2 }}
              >
                History
              </Button>
              <Button
                color="inherit"
                onClick={handleLogout}
              >
                Logout
              </Button>
            </>
          ) : (
            <>
              <Button
                color="inherit"
                component={RouterLink}
                to="/login"
              >
                Login
              </Button>
              <Button
                color="inherit"
                component={RouterLink}
                to="/register"
              >
                Register
              </Button>
            </>
          )}
        </Box>
      </Toolbar>
    </AppBar>
  );
};

export default Navbar;
